CREATE FUNCTION main.governance.tenant_row_filter(tenant_id STRING)
RETURN
  IF(
    IS_ACCOUNT_GROUP_MEMBER('platform_admins'),
    TRUE,
    tenant_id = current_user_tenant()
  );

-- current_user_tenant() resolves the caller's tenant from a mapping table,
-- keyed on the session's authenticated principal
CREATE FUNCTION main.governance.current_user_tenant()
RETURN (
  SELECT tenant_id
  FROM main.governance.user_tenant_map
  WHERE user_principal = current_user()
);

ALTER TABLE main.sales.orders
