-- Original T-SQL (relies on locking reads under READ COMMITTED)
CREATE PROCEDURE dbo.ReserveInventory (@ProductId INT, @Qty INT)
AS
BEGIN
  BEGIN TRANSACTION;
    DECLARE @Available INT;
    SELECT @Available = QtyAvailable FROM dbo.Inventory WHERE ProductId = @ProductId; -- takes a shared lock, blocks concurrent writers
    IF @Available >= @Qty
    BEGIN
      UPDATE dbo.Inventory SET QtyAvailable = QtyAvailable - @Qty WHERE ProductId = @ProductId;
      COMMIT;
    END
    ELSE
      ROLLBACK;
END

-- Migrated PostgreSQL version: MVCC read committed does NOT block concurrent readers/writers
-- the same way, so the race must be closed explicitly
CREATE OR REPLACE FUNCTION reserve_inventory(p_product_id INT, p_qty INT)
RETURNS BOOLEAN AS $$
DECLARE
  v_updated INT;
BEGIN
  UPDATE inventory
     SET qty_available = qty_available - p_qty
   WHERE product_id = p_product_id
     AND qty_available >= p_qty;      -- atomic check-and-update in one statement, closes the race

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated > 0;
END;
$$ LANGUAGE plpgsql;

