import json, sys
from jsonschema import Draft7Validator

def load(path):
    with open(path) as f:
        return json.load(f)

old_schema = load("contracts/orders.events.v1.schema.json")
new_schema = load("contracts/orders.events.v2.schema.json")
sample_payload = load("ci/fixtures/orders.events.sample.json")

# 1. the new sample payload must validate against the OLD contract too,
#    unless this PR is explicitly tagged as a major/breaking version bump
errors = list(Draft7Validator(old_schema).iter_errors(sample_payload))
breaking = bool(errors)

if breaking and "breaking-change-approved" not in sys.argv:
    print("BREAKING CHANGE detected against v1 contract. Requires explicit approval label:")
    for e in errors:
        print(f"  - {e.message}")
    sys.exit(1)
else:
    print("Contract check passed (backward-compatible or explicitly approved).")
